import{_ as a,o as e,c as i,ag as t}from"./chunks/framework.CmaAMB6e.js";const b=JSON.parse('{"title":"Frontend 学习等级体系（L1-L5）","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/levels.md","filePath":"frontend/levels.md","lastUpdated":null}'),r={name:"frontend/levels.md"};function o(d,l,h,n,s,c){return e(),i("div",null,[...l[0]||(l[0]=[t(`<h1 id="frontend-学习等级体系-l1-l5" tabindex="-1">Frontend 学习等级体系（L1-L5） <a class="header-anchor" href="#frontend-学习等级体系-l1-l5" aria-label="Permalink to &quot;Frontend 学习等级体系（L1-L5）&quot;">​</a></h1><blockquote><p>每个技能独立走 5 级阶梯。等级衡量的是「能做什么」，不是「背过什么」。每学完一级用 <code>/assess &lt;技能&gt; &lt;等级&gt;</code> 让 AI 考核，达标后再进下一级。</p><p>等级 ↔ 阶段映射以各技能 <code>learning-path.md</code> 为准；本文件定义每级的<strong>能力目标、常见错误、晋升标准、考核题型</strong>。</p></blockquote><h2 id="等级总览" tabindex="-1">等级总览 <a class="header-anchor" href="#等级总览" aria-label="Permalink to &quot;等级总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>等级</th><th>名称</th><th>定位</th><th>对应阶段</th><th>考核最低分</th></tr></thead><tbody><tr><td>L1</td><td>前端入门</td><td>讲清浏览器/JS/网络/渲染底层机制</td><td>阶段 1 · 基础体系化</td><td>80%</td></tr><tr><td>L2</td><td>框架深入者</td><td>深入理解 React 渲染 / Vue 响应式原理</td><td>阶段 2/3 · React/Vue 深度线</td><td>80%</td></tr><tr><td>L3</td><td>工程化开发者</td><td>能独立搭建质量与测试体系</td><td>阶段 4 · 工程化与质量</td><td>80%</td></tr><tr><td>L4</td><td>资深工程师</td><td>能解决生产级问题（性能/监控/安全）</td><td>阶段 5 · 架构与进阶(前段)</td><td>82%</td></tr><tr><td>L5</td><td>前端架构师</td><td>能设计架构、主导技术决策</td><td>架构与进阶(后段) + 综合实战</td><td>85%</td></tr></tbody></table><blockquote><p>L3-L5 重点考核架构论证、性能治理、代码评审等能力；已有前端基础的读者可用真实项目经历佐证 L1-L2 能力，直接进入进阶考核。</p></blockquote><hr><h2 id="level-1-·-前端入门" tabindex="-1">Level 1 · 前端入门 <a class="header-anchor" href="#level-1-·-前端入门" aria-label="Permalink to &quot;Level 1 · 前端入门&quot;">​</a></h2><h3 id="能力目标" tabindex="-1">能力目标 <a class="header-anchor" href="#能力目标" aria-label="Permalink to &quot;能力目标&quot;">​</a></h3><ul><li>讲清浏览器渲染流程（进程/主线程/合成器）</li><li>理解 JS 核心机制（闭包/原型链/this/事件循环）</li><li>掌握异步编程与网络缓存原理</li><li>理解渲染性能与 Core Web Vitals</li></ul><h3 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to &quot;常见错误&quot;">​</a></h3><ol><li>只记概念不会讲原理（面试/排查时说不出因果）</li><li>异步时序搞混（微任务/宏任务顺序）</li><li>性能问题靠猜不靠测量</li><li>只读不写，没有动手闭环</li></ol><h3 id="晋升标准" tabindex="-1">晋升标准 <a class="header-anchor" href="#晋升标准" aria-label="Permalink to &quot;晋升标准&quot;">​</a></h3><ul><li>[ ] 能画出浏览器从输入 URL 到渲染完成的全流程</li><li>[ ] 能解释事件循环执行顺序并预测代码输出</li><li>[ ] 能用 Performance API 测量页面性能指标</li><li>[ ] 通过 L1 考核</li></ul><hr><h2 id="level-2-·-框架深入者" tabindex="-1">Level 2 · 框架深入者 <a class="header-anchor" href="#level-2-·-框架深入者" aria-label="Permalink to &quot;Level 2 · 框架深入者&quot;">​</a></h2><h3 id="能力目标-1" tabindex="-1">能力目标 <a class="header-anchor" href="#能力目标-1" aria-label="Permalink to &quot;能力目标&quot;">​</a></h3><ul><li>深入理解 React 渲染模型（Fiber/协调/并发）</li><li>深入理解 Vue 响应式原理（Proxy/依赖收集）</li><li>掌握 Hooks 体系与组件设计模式</li><li>理解状态管理选型（Store vs Query vs Context）</li></ul><h3 id="常见错误-1" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误-1" aria-label="Permalink to &quot;常见错误&quot;">​</a></h3><ol><li>只懂 API 不懂原理（memo 滥用/响应式丢失）</li><li>状态层放错（服务端数据硬塞 Store）</li><li>组件 API 设计贪多（40 个 props）</li><li>性能优化方向错误（不打热点）</li></ol><h3 id="晋升标准-1" tabindex="-1">晋升标准 <a class="header-anchor" href="#晋升标准-1" aria-label="Permalink to &quot;晋升标准&quot;">​</a></h3><ul><li>[ ] 能解释一次 React 组件从 setState 到 DOM 更新的完整链路</li><li>[ ] 能解释 Vue 解构丢失响应性的原因并给出方案</li><li>[ ] 能用 React/Vue 独立实现一个中型应用（含状态管理与性能优化）</li><li>[ ] 通过 L2 考核</li></ul><hr><h2 id="level-3-·-工程化开发者" tabindex="-1">Level 3 · 工程化开发者 <a class="header-anchor" href="#level-3-·-工程化开发者" aria-label="Permalink to &quot;Level 3 · 工程化开发者&quot;">​</a></h2><h3 id="能力目标-2" tabindex="-1">能力目标 <a class="header-anchor" href="#能力目标-2" aria-label="Permalink to &quot;能力目标&quot;">​</a></h3><ul><li>独立搭建质量与测试体系（Lint/单测/E2E/CI）</li><li>理解构建工具原理（Vite/Rollup/Tree Shaking）</li><li>掌握代码规范与 Code Review 流程</li><li>理解发布流程（灰度/版本管理）</li></ul><h3 id="常见错误-2" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误-2" aria-label="Permalink to &quot;常见错误&quot;">​</a></h3><ol><li>Lint/测试只装不执行（规范形同虚设）</li><li>E2E 选择器脆弱（依赖 DOM 结构）</li><li>构建产物不分析（体积失控）</li><li>发布无灰度无回滚</li><li>测试只写 happy path</li></ol><h3 id="晋升标准-2" tabindex="-1">晋升标准 <a class="header-anchor" href="#晋升标准-2" aria-label="Permalink to &quot;晋升标准&quot;">​</a></h3><ul><li>[ ] 独立搭建一个前端工程的完整质量体系（Lint+单测+E2E+CI）</li><li>[ ] 能用构建分析工具优化产物体积</li><li>[ ] 能解释 Vite 开发与构建的原理差异</li><li>[ ] 通过 L3 考核</li></ul><hr><h2 id="level-4-·-资深工程师" tabindex="-1">Level 4 · 资深工程师 <a class="header-anchor" href="#level-4-·-资深工程师" aria-label="Permalink to &quot;Level 4 · 资深工程师&quot;">​</a></h2><h3 id="能力目标-3" tabindex="-1">能力目标 <a class="header-anchor" href="#能力目标-3" aria-label="Permalink to &quot;能力目标&quot;">​</a></h3><ul><li>状态管理与数据流架构（服务端/客户端状态分层）</li><li>微前端 / Monorepo 工程架构</li><li>性能监控与错误治理（RUM/告警/排障）</li><li>前端安全（XSS/CSRF/供应链）</li><li>可访问性与国际化合规</li></ul><h3 id="常见错误-3" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误-3" aria-label="Permalink to &quot;常见错误&quot;">​</a></h3><ol><li>架构过度设计，为了模式而用模式</li><li>性能优化方向错误，不打热点</li><li>监控告警噪音大（无法区分真问题）</li><li>忽视边界条件与弱网/离线场景</li><li>安全合规遗漏（XSS/权限/依赖漏洞）</li></ol><h3 id="晋升标准-3" tabindex="-1">晋升标准 <a class="header-anchor" href="#晋升标准-3" aria-label="Permalink to &quot;晋升标准&quot;">​</a></h3><ul><li>[ ] 为一个已有项目引入状态分层架构并论证取舍</li><li>[ ] 用性能监控定位并修复一个真实性能问题</li><li>[ ] 排查并复盘一次线上事故（含告警到修复全流程）</li><li>[ ] 通过 L4 考核（含架构答辩 + 性能分析）</li></ul><hr><h2 id="level-5-·-专家-架构师" tabindex="-1">Level 5 · 专家/架构师 <a class="header-anchor" href="#level-5-·-专家-架构师" aria-label="Permalink to &quot;Level 5 · 专家/架构师&quot;">​</a></h2><h3 id="能力目标-4" tabindex="-1">能力目标 <a class="header-anchor" href="#能力目标-4" aria-label="Permalink to &quot;能力目标&quot;">​</a></h3><ul><li>独立设计前端架构（微前端/SSR/Monorepo 选型论证）</li><li>主导前端安全与性能治理体系</li><li>设计系统与组件库建设</li><li>主导代码评审、生产事故复盘</li><li>沉淀自己的工程 checklist</li></ul><h3 id="常见错误-4" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误-4" aria-label="Permalink to &quot;常见错误&quot;">​</a></h3><ol><li>为技术而技术（微前端/SSR 滥用，不考虑成本）</li><li>不沉淀复盘，同样的坑反复踩</li><li>无法权衡架构复杂度与业务价值</li><li>忽视团队工程效能（规范/工具链落地）</li></ol><h3 id="晋升标准-4" tabindex="-1">晋升标准 <a class="header-anchor" href="#晋升标准-4" aria-label="Permalink to &quot;晋升标准&quot;">​</a></h3><ul><li>[ ] 独立完成综合实战项目（含架构设计文档 + 性能/安全考量）</li><li>[ ] 能设计并论证一个完整前端架构方案（含选型对比与成本）</li><li>[ ] 能评审他人代码并给出建设性意见</li><li>[ ] 通过 L5 考核（项目答辩 + 代码评审）</li></ul><hr><h2 id="等级跃迁图" tabindex="-1">等级跃迁图 <a class="header-anchor" href="#等级跃迁图" aria-label="Permalink to &quot;等级跃迁图&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L1 前端入门 ─(讲清底层机制)→ L2 框架深入者 ─(框架原理)→ L3 工程化开发者</span></span>
<span class="line"><span>    ─(质量体系)→ L4 资深工程师 ─(架构与治理)→ L5 专家/架构师</span></span></code></pre></div><h2 id="使用约定" tabindex="-1">使用约定 <a class="header-anchor" href="#使用约定" aria-label="Permalink to &quot;使用约定&quot;">​</a></h2><ol><li>每级学完用 <code>/assess &lt;技能&gt; &lt;等级&gt;</code> 考核，达标再升级</li><li>考核记录追加到该技能 <code>progress.md</code>，不覆盖历史</li><li>未通过时按 <code>assess</code> 给出的补学路径复习，不重复考试</li><li>L4/L5 考核包含架构答辩与代码评审，不只是选择题</li></ol>`,50)])])}const q=a(r,[["render",o]]);export{b as __pageData,q as default};
